BEGIN;
DO $guard$ BEGIN IF current_database() <> 'QuotationRequest' THEN RAISE EXCEPTION 'database identity mismatch'; END IF; END $guard$;
ALTER TABLE "public"."Request" ADD COLUMN "JourneyId" uuid;
ALTER TABLE "public"."Request" ADD COLUMN "QualificationState" character varying(32) DEFAULT ('unreviewed') NOT NULL;
ALTER TABLE "public"."Request" ADD COLUMN "QualificationStateChangedUtc" text;
ALTER TABLE "public"."Request" ADD COLUMN "QualificationVersion" integer DEFAULT ((0)) NOT NULL;
ALTER TABLE "public"."Request" ADD COLUMN "TransactionId" character varying(128);
CREATE TABLE "public"."RequestQualificationAudit" ("ID" bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1) NOT NULL, "RequestID" integer NOT NULL, "JourneyId" uuid, "TransactionId" character varying(128) NOT NULL, "IdempotencyKey" character varying(128) NOT NULL, "PreviousState" character varying(32) NOT NULL, "NewState" character varying(32) NOT NULL, "Completeness" character varying(32), "DuplicateCount" integer NOT NULL, "UnmatchedClassification" character varying(64), "ChangedBy" character varying(256) NOT NULL, "ChangedUtc" text NOT NULL, "Reason" character varying(512), "Version" integer NOT NULL);
ALTER TABLE "public"."RequestQualificationAudit" ADD CONSTRAINT "PK_RequestQualificationAudit" PRIMARY KEY ("ID");
ALTER TABLE "public"."RequestQualificationAudit" ADD CONSTRAINT "CK_RequestQualificationAudit_DuplicateCount" CHECK (("DuplicateCount">=(0)));
ALTER TABLE "public"."RequestQualificationAudit" ADD CONSTRAINT "CK_RequestQualificationAudit_NewState" CHECK (("NewState"='incomplete' OR "NewState"='stale' OR "NewState"='duplicate' OR "NewState"='not_qualified' OR "NewState"='qualified' OR "NewState"='unreviewed'));
ALTER TABLE "public"."RequestQualificationAudit" ADD CONSTRAINT "CK_RequestQualificationAudit_Reason" CHECK (("NewState"='qualified' OR nullif(ltrim(rtrim("Reason")),'') IS NOT NULL));
CREATE INDEX "IX_RequestQualificationAudit_JourneyId" ON "public"."RequestQualificationAudit" ("JourneyId" ASC) WHERE ("JourneyId" IS NOT NULL);
CREATE UNIQUE INDEX "UX_RequestQualificationAudit_RequestID_IdempotencyKey" ON "public"."RequestQualificationAudit" ("RequestID" ASC, "IdempotencyKey" ASC);
CREATE INDEX "IX_Request_JourneyId" ON "public"."Request" ("JourneyId" ASC) WHERE ("JourneyId" IS NOT NULL);
ALTER TABLE "public"."Request" ADD CONSTRAINT "CK_Request_QualificationState" CHECK (("QualificationState"='incomplete' OR "QualificationState"='stale' OR "QualificationState"='duplicate' OR "QualificationState"='not_qualified' OR "QualificationState"='qualified' OR "QualificationState"='unreviewed'));
CREATE UNIQUE INDEX "UX_Request_TransactionId" ON "public"."Request" ("TransactionId" ASC) WHERE ("TransactionId" IS NOT NULL);
ALTER TABLE "public"."RequestQualificationAudit" ADD CONSTRAINT "FK_RequestQualificationAudit_Request" FOREIGN KEY ("RequestID") REFERENCES "public"."Request" ("ID") ON DELETE NO ACTION ON UPDATE NO ACTION NOT DEFERRABLE NOT VALID;
ALTER TABLE "public"."RequestQualificationAudit" VALIDATE CONSTRAINT "FK_RequestQualificationAudit_Request";
COMMIT;
